    faq_a_bag_examples_list: "Túi mới có sẵn các ví dụ mà bạn có thể sửa hoặc xóa như mọi thứ khác: Nhà (đi chợ, công thức nấu ăn, thực đơn tuần này), Gia đình (khoảnh khắc nhỏ, danh sách cho tiệc sinh nhật, hoạt động và lớp học), Ý tưởng (ý tưởng cuối tuần, ý tưởng quà tặng theo mức độ thân thiết với người nhận, và làm gì với số tiền đã tiết kiệm) và Du lịch (những nơi bạn muốn đến, đồ mang theo khi đi chơi, đồ mang đi khách sạn và danh sách bay ra nước ngoài). Túi đã có từ trước sẽ nhận các ví dụ mới nhất một lần, vào chính các ngăn của túi.",
    faq_q_bag_examples_list: "Túi của tôi có những ví dụ nào?",
    faq_a_nm_me1_guide: "Sky – nhân vật của bạn trong New Me, ở hình dạng đầu tiên (Sky 1). Lần đầu tiên, ngay sau khi tham gia, một cánh cổng ánh sáng mở ra giữa muôn tia lấp lánh và Sky bay ra từ đó, giải thích qua vài lần chạm những gì đang chờ phía trước, rồi ở bên cạnh mỗi câu hỏi: khi chọn bữa ăn, Sky cùng bạn viết vào cuốn sách của Sky, và chạm vào lời khuyên sẽ hiện ra một lời khuyên khác. Cuối cùng, Sky ăn mừng cùng bạn và dẫn bạn đi một vòng tham quan ngắn – và khi chuyến tham quan kết thúc, Sky còn một khoảnh khắc nhỏ nữa bên bạn. Nếu bạn rời đi giữa chừng – lúc đang trả lời câu hỏi hay đang tham quan – lần sau Sky sẽ vui mừng gặp lại bạn và hỏi có muốn tiếp tục từ chỗ cũ không.",
