    shop_win_noon: "Chiều",
    shop_win_other: "Khác…",
    shop_win_to: "Đến",
    room_genie_again_no: "Giờ thì chưa",
    room_genie_again_no_msg: "Vậy thì đã đến lúc chinh phục những mục tiêu bạn đã đặt ra. Khi bạn đến mục tiêu tiếp theo – sẽ có điều gì đó đang chờ bạn ở đó ✨",
    room_genie_again_q: "Lại ghé thăm rồi à? ✨ Bạn có muốn thay đổi thêm điều gì trong cuộc sống không?",
    room_genie_again_yes: "Có",
    room_genie_bye: "Hẹn gặp lại",
    room_genie_rest: "Tinh linh rừng đang nghỉ ngơi – ngày mai hãy quay lại nhé ✨",
    faq_a_shop_holidays: "Trong Danh Sách Mua Sắm, chạm vào món quà: các ngày lễ của quốc gia bạn (chọn trong Cài Đặt) hiện ra theo thứ tự, kèm ngày – được tự tính mỗi năm. Chạm vào một ngày lễ để mở danh sách soạn sẵn những thứ mọi người thường mua cho dịp đó; mọi thứ đều được chọn sẵn (trừ những gì đã có trong danh sách của bạn), bỏ chọn những gì không cần rồi chạm “Thêm vào danh sách”. Hai tuần trước ngày lễ, một thẻ nhỏ sẽ hiện ở đầu danh sách; ✕ ẩn thẻ đó cho đến ngày lễ tiếp theo.",
    faq_q_shop_holidays: "“Mua gì cho ngày lễ” hoạt động thế nào?",
    shop_hol_add: "Thêm vào danh sách ({n})",
    shop_hol_added: "Đã thêm vào danh sách: {n}",
    shop_hol_btn: "Mua gì cho ngày lễ",
    shop_hol_items_title: "{holiday} – mua gì?",
    shop_hol_not_now: "Để sau",
    faq_a_shop_delivery: "Trong Danh Sách Mua Sắm, chạm vào chiếc xe tải: chọn đơn giao có gì (tất cả đều được chọn sẵn), khi nào đến – hôm nay, ngày mai hay ngày khác – và vào giờ nào (sáng, chiều, tối, hoặc “Khác…” để tự chọn giờ). Các món đó chuyển sang thẻ “Đang giao” ở đầu danh sách, kèm ngày và khung giờ. Khi đến ngày, “Đơn giao đã đến chưa?” sẽ hiện trong Ngày Của Tôi (và trên thẻ có “Đã đến chưa?”). Nếu đã đến đủ, các món chuyển sang “Mua lại”. Nếu thiếu gì đó, chạm vào món chưa đến và nó sẽ trở lại danh sách ngay.",
    faq_a_shop_departments: "Danh sách tự sắp xếp theo các quầy trong siêu thị – rau củ quả, bánh mì, sữa & trứng, thịt & cá, đồ khô, đồ đông lạnh, đồ uống, đồ ăn vặt, vệ sinh, chăm sóc cá nhân, đồ cho bé và thú cưng – để bạn đi qua các dãy kệ theo thứ tự. Quầy được nhận diện từ tên món. Nếu một món bị xếp nhầm chỗ, hãy chạm vào nó và chọn quầy, hoặc chọn “Khác…” để tự viết.",
    faq_a_shop_share_qty: "Có. Cạnh mỗi món, + thêm một (×2, ×3…) và − bớt một. Nút chia sẻ ở đầu Danh Sách Mua Sắm gửi cả danh sách, sắp xếp gọn gàng theo quầy, qua WhatsApp, email hoặc dưới dạng bản sao.",
    faq_a_shop_two_buttons: "Cả hai đều có nghĩa là “đã mua”. ✕ dành cho thứ bạn chỉ mua một lần – nó rời khỏi danh sách (và nằm chờ trong 🗑️ Lưu trữ phòng khi nhầm). ↺ dành cho những thứ bạn mua đi mua lại – nó rời khỏi danh sách và nằm chờ trong “Mua lại”: nút ↺ nhỏ cạnh thùng rác ở cuối danh sách sẽ mở mục này, và chạm một lần ở đó là một món trở lại danh sách. Trong “Sửa” ở đó, bạn có thể bỏ một món ra. Khi bạn thêm một món, những thứ bạn từng mua sẽ hiện ra làm gợi ý, và nếu món đó đã có trong danh sách, nó chỉ thành ×2 thay vì thêm một dòng nữa.",
    faq_q_shop_delivery: "“Tôi đã đặt giao hàng” hoạt động thế nào?",
