    nm_demo_title: "Đổi món như thế nào",
    faq_a_new_me_challenge_journal: "Khi một thử thách kết thúc – thử thách lớn, thử thách nhỏ hay thử thách của tuần – màn ăn mừng có nút 📝 Diễn ra thế nào? để mở một trang trong nhật ký thử thách: cảm giác ra sao (năm khuôn mặt), điều gì đã giúp ích, điều gì khó khăn và tôi sẽ mang theo điều gì – không mục nào bắt buộc, và cũng có thể để lát nữa. Nhật ký là một viên kim cương trong ba lô kỳ diệu: mỗi thử thách đã hoàn thành cùng ngày và những gì đã viết, mới nhất ở trên cùng – chạm vào một thử thách để đọc, sửa hoặc chia sẻ (chỉ những gì có trên trang được chia sẻ). Thử thách đã hoàn thành cũng nhận một huy chương trong thành tích, ở mục “Thử thách tôi đã hoàn thành”. Nhật ký thử thách tách riêng với cuốn nhật ký thông thường.",
    faq_q_new_me_challenge_journal: "Nhật ký thử thách là gì?",
