    nm_chj_write: "Viết xem đã diễn ra thế nào",
    nm_swap_time: "Giờ",
    faq_a_ai_reminder_in_text: "Có – hãy viết nó cùng với công việc, ví dụ “mai lúc 17:00 đi lấy gói hàng, nhắc trước một tiếng”. Nhắc nhở được lưu ngay trên công việc đó: trước một tiếng, trước nửa tiếng, trước một ngày, v.v., còn “nhắc tôi” mà không có giờ nghĩa là trước 10 phút. Nhắc nhở viết trong văn bản được ưu tiên hơn ô nhắc nhở trong cùng cửa sổ.",
    faq_q_ai_reminder_in_text: "Tôi có thể nhờ trợ lý AI đặt nhắc nhở ngay trong cùng một yêu cầu không?",
    myday_meals_all_done: "Đã đánh dấu tất cả các bữa ăn hôm nay 🍽️",
    nm_tour_week_text: "Một thử thách nhỏ cho tuần. ✓ mỗi ngày – hết tuần nhận một chìa khóa.",
    books_home_chip: "{title} · tr. {page}",
    books_home_of: "trên {total}",
    books_home_off_toast: "Cuốn sách đã rời màn hình chính",
    books_home_on_toast: "Cuốn sách đã lên màn hình chính 📖",
    books_home_pin: "Trên màn hình chính",
    books_home_q: "Tôi đang ở trang nào?",
    books_home_save: "Lưu",
    faq_a_books_home_chip: "Có. Trong Góc đọc sách, trên thẻ của cuốn sách đang đọc, chạm 📌 Trên màn hình chính. Một nút nhỏ hiện sách và trang sẽ xuất hiện dưới lời chào trên màn hình chính – chạm vào, nhập số trang mới rồi lưu, tiến độ sẽ được ghi lại (cả trong Góc đọc sách). Chạm 📌 lần nữa để gỡ xuống. Có thể ghim nhiều cuốn sách cùng lúc – mỗi cuốn một nút – và giống nhau trên mọi thiết bị.",
    faq_a_new_me_week_challenge: "Một thử thách nhỏ trong một tuần, do bạn tự chọn. Ở hành lang có một tấm thẻ lớn: “Tuần này bạn muốn rèn luyện điều gì?” – chạm vào đó, chọn một lĩnh vực (với chính mình, với người khác, học hỏi và trưởng thành, bình yên, những bước can đảm nhỏ, nhà cửa và thói quen) cùng một thử thách, rồi chọn thời điểm bắt đầu. Các thử thách này cũng có trong màn hình thử thách, mục 🌱 Phát triển bản thân. Mỗi ngày đánh dấu ✓ trên thẻ (được nghỉ một ngày mỗi tuần), và mỗi tuần kết thúc sẽ mang về một chiếc chìa khóa mới cho thế giới bí mật. “Đọc 2 trang mỗi ngày” tự đánh dấu từ các trang ghi trong Góc đọc sách. Khi tuần kết thúc, 📌 Giữ lại làm việc hằng ngày sẽ thêm thử thách vào Thói Quen Của Tôi vào giờ bạn chọn, kèm ✓ mỗi ngày. Mỗi lần chỉ chạy một thử thách của tuần; các thử thách lớn và nhỏ vẫn tiếp tục song song.",
    faq_a_room_genie: "Ở hiên nhà nhìn ra biển, chạm vào cây đèn Aladdin sẽ gọi tinh linh rừng ra – và một cuộc trò chuyện bắt đầu: điều ước của bạn là gì (bạn muốn thay đổi điều gì trong cuộc sống), cảm giác sẽ ra sao khi thành hiện thực, điều gì khó khăn trên đường đi, và làm sao biến hoàn cảnh hiện tại thành điều tốt đẹp. Sau đó là khoảng bao lâu, một bước nhỏ đầu tiên cùng hai bước nữa, và một câu “nếu… thì…” cho lúc gặp khó khăn. Cuối cùng cả điều ước hiện ra từng bước một, và có thể biến thành mục tiêu trong Mục Tiêu Của Tôi (các bước trở thành những cột mốc trên đường, kèm ngày theo thời gian đã chọn; ở đó có thể thay đổi mọi thứ) hoặc lưu vào nhật ký – rồi tinh linh nói lời tạm biệt. Không có gì được lưu nếu không chọn một trong hai. Từ lần ghé thăm thứ hai trở đi, tinh linh sẽ hỏi trước xem bạn có muốn thay đổi thêm điều gì trong cuộc sống không: có – cùng cuộc trò chuyện đó; giờ thì chưa – một lời nhắc chinh phục những mục tiêu đã đặt ra. Tinh linh xuất hiện mỗi ngày một lần: sau khi một điều ước được lưu (hoặc sau khi chọn “Giờ thì chưa”), tinh linh nghỉ đến ngày mai. Các câu hỏi dựa trên một cách quen thuộc để biến điều ước thành kế hoạch: điều ước, kết quả, trở ngại và kế hoạch.",
    faq_q_books_home_chip: "Tôi có thể xem sách và trang đang đọc ngay trên màn hình chính không?",
    faq_q_new_me_week_challenge: "Thử thách của tuần là gì?",
