    room_drawer_aria: "Tủ nhỏ",
    nm_me_choose: "Chọn",
    nm_me_on_screen: "Trên màn hình",
    faq_a_new_me_game: "Trong New Me, các nút trò chơi luôn ở cùng một chỗ – ở hành lang, trong căn phòng bí mật và khắp nơi trong rừng; chỉ có bức tranh ở giữa thay đổi. Phía trên: ngày thứ mấy trong hành trình, chìa khóa, chuỗi ngày và năng lượng hôm nay (đã ăn bao nhiêu so với kế hoạch), bên dưới là nhiệm vụ tiếp theo – bữa tiếp theo đúng giờ của bữa đó (chạm để mở, có ✓ Đã ăn). Bên cạnh: cả ngày, thử thách và hành trình của tôi, và kế bên là thử thách của tuần – 7 ngày của nó và ✓ cho hôm nay. Phía dưới: ba lô kỳ diệu (toàn bộ New Me – bản đồ thế giới, hành trình của tôi, danh sách mua sắm, thành tích, nhật ký thử thách, số đo cơ thể, ảnh tiến trình, lịch tháng, bảng hằng ngày, nhắc nhở, PDF thực đơn và cài đặt; mở ra như một màn hình riêng). Bản đồ thế giới, thứ đầu tiên trong ba lô, hiển thị mọi nơi trong rừng – chạm vào một nơi để đến đó; nơi bị khóa cho biết cần bao nhiêu chìa khóa. Sky là nhân vật của bạn trên lối mòn trong rừng: Sky bắt đầu là Sky 1, sau vài thử thách (4 chìa khóa) lớn lên thành Sky 2 và gần cuối (9 chìa khóa) thành Sky 3 – với màn lột xác có thể tận mắt xem. Chạm vào Sky để xem mọi giai đoạn – giai đoạn nào đã đạt được đều có thể chọn lại, nên giai đoạn trước đó có thể quay lại. Sky lơ lửng – kéo bằng ngón tay hoặc chuột, lối vào mà Sky chạm tới sẽ mở ra (lối vào bị khóa cho biết còn thiếu bao nhiêu chìa khóa). Sky cũng đi theo vào mọi căn phòng và mọi nơi, và lơ lửng ở bất cứ đâu bạn để lại: kéo Sky đến bất cứ chỗ nào, và kéo vòng sáng bên dưới để xoay Sky trọn một vòng; Sky quay mặt theo hướng di chuyển (trên máy tính: phím mũi tên để di chuyển, Q và E để xoay). Ở hành lang, biểu tượng 🏠 nhỏ dưới thanh trên cùng sẽ quay về màn hình chính; trong mỗi căn phòng và mỗi nơi, nút ở cùng góc đó sẽ quay về hành lang.",
    faq_q_new_me_game: "Các nút trò chơi, bản đồ thế giới và Sky hoạt động thế nào?",
