    room_magic_song_rec3: "Chuông gió thác nước",
    faq_a_new_me_menu_build: "Đầu tiên, bảng câu hỏi hỏi bạn ăn những bữa nào và lúc nào (2 bữa chính + 1 bữa phụ, 2 bữa chính + bữa tối nhẹ, hoặc cả hai), và buổi tối có gì không – ăn hay uống, món gì và lúc mấy giờ. Với “2 bữa chính + 1 bữa phụ”, các bữa chính là bữa trưa (11:30) và bữa tối (19:00), bữa phụ lúc 16:00. Sau đó tất cả lựa chọn cho các bữa đó hiện ra. Chọn tối đa 2 món yêu thích cho mỗi bữa – thực đơn sẽ ghi “món này hoặc món kia”. Ở một số lựa chọn (pita và đồ phết, ngũ cốc và sữa, món nhẹ), bạn chọn tối đa 3 thứ bạn thích, mỗi thứ có khẩu phần riêng, và thực đơn sẽ ghi “thứ này hoặc thứ kia hoặc thứ khác”; lượng calo theo những gì bạn chọn. Cà phê và đồ uống cũng vậy. Mọi lựa chọn đều được cân bằng, nên tổng cả ngày đúng 1.300 hoặc 1.500. Để thay đổi bất cứ lúc nào: ⚙️ Cài đặt → 🍽️ Tạo thực đơn của bạn, hoặc “Chọn tối đa 3 thứ bạn thích” trên thẻ của bữa ăn.",
