    faq_a_myday_water_toggle: "Có. Ly nước trong ‘Ngày Của Tôi’ (có + để thêm một ly) hiển thị mặc định. Để ẩn, tắt “Hiển thị nước trong ‘Ngày Của Tôi’” trong Cài đặt > Cá Nhân Hóa & Lịch. Không có gì bị xóa – Theo Dõi Uống Nước vẫn hoạt động, và bật lại thì ly nước quay lại.",
