    faq_a_routine_newme_sync: "Khi có New Me, ⚙️ của Thói Quen Của Tôi có công tắc ‘Đồng bộ với New Me’. Khi bật (mặc định), các bữa ăn New Me hôm nay hiện trong Ngày Của Tôi và Thói Quen Của Tôi – thay chỗ những bữa trong thói quen đã được ẩn. Khi tắt, bữa ăn New Me rời khỏi cả hai nơi và thói quen trở lại đúng như cũ. Không có gì bị xóa – bật lại sẽ đưa mọi thứ trở về và hỏi nên ẩn những bữa nào trong thói quen.",
