    faq_a_food_list_languages: "Danh sách món ăn có sẵn ban đầu gồm các món Israel với tên tiếng Do Thái. Ở mọi ngôn ngữ khác, mỗi món hiển thị bằng tên tiếng Anh, và ô tìm kiếm tìm theo mọi tên tiếng Anh mà nó biết (ví dụ 'broth' tìm ra Clear soup); những món chỉ có tên tiếng Do Thái sẽ không hiện ở đó. Món nào không có trong danh sách, bạn chỉ cần viết bằng lời của mình – ước tính bằng AI hoạt động ở mọi ngôn ngữ.",
    faq_q_food_list_languages: "Vì sao danh sách món ăn hiển thị tên tiếng Anh, và ít món hơn, trong ngôn ngữ của tôi?",
    settings_copyright_line: "© 2026 bảo lưu mọi quyền. ứng dụng được phát triển bởi eden zabari.",
    workout_ready_replace_btn: "Thay thế",
    faq_a_sport_workout_ai: "Trong Buổi tập của tôi → ⋯ → Kế hoạch bằng AI (và khi bảng còn trống, cả ở ô bên cạnh các kế hoạch có sẵn). Trả lời bằng vài lần chạm – mấy lần mỗi tuần, khi nào, địa điểm, trình độ và mục tiêu, hầu hết đều có \"Khác\" – và nếu muốn, thêm một dòng tự do, như đầu gối nhạy cảm hoặc chạy 5 km trước mùa hè. AI tạo cả một tuần: loại buổi tập, ngày, giờ, thời lượng, cường độ, bài tập và ngày nghỉ. Trước khi lưu sẽ có bản xem trước: \"Đưa vào bảng của tôi\" (thay cho bảng hoặc thêm vào), \"Gợi ý khác\" (tối đa 3 lần) hoặc \"Đổi câu trả lời\". Kế hoạch được giữ vừa phải có chủ ý, và nếu bạn nhắc đến cơn đau hay chấn thương, bạn sẽ nhận các lựa chọn nhẹ nhàng kèm lời khuyên hỏi ý kiến chuyên gia. Tính năng dùng chung hạn mức AI với lịch và thói quen: miễn phí 5 lần, và 60 lần mỗi tháng với Premium.",
