    faq_a_sport_workout_jar: "Mỗi loại buổi tập có một ngôi sao màu riêng – chạy màu hồng, đi bộ màu xanh lá, bơi màu xanh dương, v.v. Mỗi buổi tập được ghi trong tuần này, từ bảng hay ghi riêng, đều thả ngôi sao của nó vào chiếc lọ ở đầu mục Buổi tập của tôi, và lọ đầy dần đến mục tiêu tuần (chạm vào để đổi mục tiêu). Khi đạt mục tiêu, chiếc lọ phát sáng. Chiếc lọ nhỏ bên cạnh đếm số tuần liên tiếp bạn làm đầy nó.",
    faq_q_sport_workout_jar: "Những ngôi sao màu và chiếc lọ trong Buổi tập của tôi là gì?",
    faq_a_sport_workout_gcal: "Có – trong ⋯ → Google Lịch (sau khi kết nối Google Lịch trong Cài đặt). Mỗi buổi tập có giờ sẽ thành một sự kiện lặp lại hằng tuần vào các ngày của nó, và thay đổi trong ứng dụng sẽ cập nhật theo. Nhắc nhở chỉ đến từ ứng dụng, nên Google không thêm nhắc nhở riêng, và buổi tập không bao giờ hiện hai lần trong ứng dụng. Chạm lần nữa chỉ gỡ các buổi tập khỏi Google Lịch.",
    faq_q_sport_workout_gcal: "Buổi tập có thể hiện trong Google Lịch không?",
    workout_gcal_btn: "Google Lịch",
    workout_gcal_error: "Không cập nhật được Google Lịch – sẽ thử lại ở lần thay đổi tới",
    workout_gcal_not_connected: "Hãy kết nối Google Lịch trong Cài đặt trước",
    workout_gcal_off_toast: "Đã gỡ các buổi tập khỏi Google Lịch",
    workout_gcal_on_toast: "Các buổi tập đã vào Google Lịch",
    faq_a_sport_workout_reminder: "Có – trong một buổi tập, Nhắc nhở: trước 10 phút, 30 phút hoặc một giờ, hoặc thời gian tùy chọn (buổi tập cần có giờ). Nó reo giống các nhắc nhở khác, một lần và ở một nơi: trong ứng dụng nếu đang mở, nếu không thì trên điện thoại. \"Xong\" ghi buổi tập vào lịch sử, còn \"Chưa\" sẽ nhắc lại sau 5 phút.",
    faq_q_sport_workout_reminder: "Tôi có thể nhận nhắc nhở trước buổi tập không?",
    workout_reminder_30min: "Trước 30 phút",
    workout_reminder_label: "Nhắc nhở",
    workout_reminder_need_time: "Thêm giờ để nhận nhắc nhở",
    faq_a_sport_workout_share: "Trong ⋯ → Chia sẻ, cả tuần thành một ảnh kiểu kính theo màu giao diện của bạn, kèm liên kết nhẹ nhàng tới ứng dụng (trên điện thoại sẽ mở thẳng menu chia sẻ, trên máy tính ảnh được lưu lại). ⋯ → PDF để in mở một trang gọn gàng của cả tuần, có ô để đánh dấu cạnh mỗi buổi tập và bài tập – chọn \"Lưu dưới dạng PDF\" hoặc in ra. Kế hoạch cũng xuất hiện trong báo cáo dữ liệu ở Cài đặt, phần Thể thao.",
    faq_q_sport_workout_share: "Làm sao chia sẻ hoặc in tuần tập luyện?",
    share_image_saved: "Ảnh đã được lưu – bạn có thể đính kèm",
    share_save_image: "Lưu ảnh",
    workout_pdf_btn: "PDF để in",
    workout_share_btn: "Chia sẻ",
    faq_a_sport_workout_board: "Trong ⋯ → Bảng tuần, mỗi ngày là một cột: kéo buổi tập sang ngày khác (trên điện thoại, nhấn giữ trước). Trong một buổi tập, \"Cũng vào Thói Quen Của Tôi\" đưa nó vào thói quen theo giờ và ngày của nó, và thay đổi được đồng bộ cả hai chiều; từ một mục trong Thói Quen Của Tôi, \"Thêm vào buổi tập của tôi\" làm ngược lại. ✓ ở bất kỳ chỗ nào cũng tính cho cả hai, và trong Ngày Của Tôi nó chỉ hiện một lần – trong nhãn cạnh mục nước.",
    faq_q_sport_workout_board: "Làm sao chuyển buổi tập sang ngày khác và nối với Thói Quen Của Tôi?",
    routine_in_workouts_btn: "Mở trong buổi tập của tôi",
