    workout_delete_confirm_routine: "Buổi tập sẽ bị xóa khỏi kế hoạch và Thói Quen Của Tôi. Những buổi đã ghi trong lịch sử vẫn còn.",
    workout_moved: "Đã chuyển sang {day}",
    workout_routine_need_time: "Thêm giờ để đưa vào Thói Quen Của Tôi",
    workout_routine_toggle: "Cũng vào Thói Quen Của Tôi",
    workout_view_board: "Bảng tuần",
    workout_view_timeline: "Dòng thời gian",
    faq_a_sport_workout_plan: "Trong Theo Dõi Tập Luyện, mục \"Buổi tập của tôi\": + Buổi tập – loại, ngày, giờ, thời lượng, cường độ và địa điểm (có cả \"Khác\"). Các buổi sức mạnh, chức năng và bơi có thể kèm danh sách bài tập, còn \"Nghỉ\" đánh dấu ngày nghỉ. Bạn cũng có thể bắt đầu từ một kế hoạch có sẵn. Buổi tập hôm nay hiện to, cả tuần nằm bên dưới; ✓ ghi nó vào lịch sử tập luyện cùng cường độ. Trong ⋯ bạn đặt mục tiêu tuần (số buổi hoặc số phút) – mỗi buổi tập hoàn thành sẽ thả ngôi sao của nó vào chiếc lọ.",
    faq_a_sport_workout_today: "Trong Ngày Của Tôi, cạnh mục nước, một nhãn nhỏ hiện buổi tập hôm nay – chạm vào để mở chi tiết, ✓ và ▶. ▶ bắt đầu hẹn giờ, và nó vẫn chạy trong nhãn ở màn hình chính; \"Kết thúc\" ghi buổi tập với thời gian thật. Nếu thử thách \"Hai tuần vận động\" trong New Me đang diễn ra, buổi tập đã ghi sẽ tự được tính vào.",
