    faq_a_new_me_magic_themes: "Năm giao diện lấp lánh có sẵn trong New Me: Khu rừng phép thuật, Bụi sao, Tiên hoa hồng, Cực quang kỳ diệu và Hoàng hôn vàng. Chọn một cái trong New Me (⚙️ Cài đặt > Màu sắc) hoặc trong Cài Đặt > Giao Diện & Hiển Thị, và một cây cọ lấp lánh sẽ tô màn hình theo giao diện đó. Giao diện phép thuật thêm ánh lấp lánh khắp ứng dụng và ở mỗi lần chạm. Bạn có thể đổi lại giao diện khác bất cứ lúc nào.",
