    quotes_look_wall: "Bức tường",
    theme_magic_section_label: "Giao diện phép thuật của New Me",
    apptour_focus_text: "Mọi thứ lùi lại, chỉ còn một việc cho lúc này – với dấu ✓ to. Xong thì việc tiếp theo hiện ra.",
    apptour_m_presets_text: "Các bữa ăn đã lưu ở một chỗ: tìm kiếm, dùng gần đây, theo giờ trong ngày – và ＋ thêm một bữa vào hôm nay.",
    apptour_night_text: "🌙 làm tối toàn bộ ứng dụng; ☀️ mang ban ngày trở lại.",
    apptour_noteline_text: "Viết rồi chạm ➤ – sẽ được lưu vào ghi chú. 📝 ở đầu dòng chuyển sang 🛒 mua sắm hoặc 🍎 bữa ăn đã lưu.",
    apptour_search_text: "Ghi chú, mua sắm, lịch, công thức, sổ tay, mục tiêu, bảng và sách – một lần tìm là thấy hết.",
    faq_a_new_me_ai_menu: "Trước thực đơn, bảng câu hỏi hỏi bạn ăn những bữa nào và lúc nào (2 bữa chính + 1 bữa phụ, 2 bữa chính + bữa tối nhẹ, hoặc cả hai), buổi tối có ăn chút gì nhỏ không và lúc mấy giờ, bạn không ăn gì, và bạn uống cà phê hay trà thế nào. Sau đó AI lập 3 lựa chọn cho mỗi bữa – mỗi lựa chọn vừa đúng phần của bữa đó trong ngày, nên tổng cả ngày vẫn đúng 1.300 hoặc 1.500 – cùng gợi ý đồ uống được lưu thành đồ uống cố định của bạn. Chọn tối đa 2 món yêu thích cho mỗi bữa; các lựa chọn của thực đơn gốc nằm ngay bên dưới, và trong 🔄 Đổi món chúng xuất hiện sau thực đơn riêng của bạn. 🔄 Lựa chọn khác lập một bộ mới (3 lần cho mỗi bảng câu hỏi). Để đổi câu trả lời hoặc lập thực đơn mới bất cứ lúc nào: ⚙️ Cài đặt → ✨ Thực đơn riêng (AI).",
    faq_q_new_me_ai_menu: "Thực đơn riêng trong New Me hoạt động thế nào?",
    nm_ai_menu_building: "Đang lập thực đơn theo các bữa và giờ của bạn…",
