    settings_sub_status_newme: "Premium đã có trong New Me của bạn.",
    room_back_to_shelf: "Về kệ",
    faq_a_new_me_day_total: "Mỗi ngày cộng lại đúng kế hoạch: các bữa ăn, khoảng 150 calo cho cà phê và đồ uống trong ngày, và những gì đã chọn cho buổi tối – chút gì nhỏ để ăn hoặc thứ gì đó để uống. Cho buổi tối, chọn tối đa 3 thứ bạn thích (ví dụ một quả chuối, một hũ sữa chua hoặc 2 miếng sô-cô-la đen; hoặc trà thảo mộc, trà với chút sữa hoặc sữa ấm), và lượng calo của chúng được lấy từ các bữa ăn. Mỗi lựa chọn tự cân bằng: một lựa chọn nhỏ hơn hoặc lớn hơn, một bữa đã bỏ, bữa sáng nhỏ và bữa nhỏ đi kèm, hay buổi tối – phần chênh lệch được cộng vào hoặc trừ khỏi các bữa, mỗi bữa theo độ lớn của nó, và dưới mỗi bữa có ghi bao nhiêu (+ hoặc −) và có thể thêm hoặc bớt gì. Bữa đã đánh dấu thì giữ nguyên như đã ghi. Trong bảng câu hỏi, mỗi bữa hiện phần điều chỉnh của nó, và một ô nhỏ hiện các bữa, đồ uống, buổi tối và tổng. Hôm đó muốn ăn món khác? Giữ tổng bằng lượng calo đó hoặc ít hơn.",
    faq_q_new_me_day_total: "Làm sao một ngày New Me cộng lại đúng 1.300 / 1.500, và đồ uống tính vào đâu?",
