    books_quotes_chip: "Trích dẫn",
    faq_a_book_quotes: "Trên kệ trong căn phòng bí mật (Trích dẫn), hoặc qua nhãn nhỏ 💬 Trích dẫn trong Góc đọc sách – đều là cùng một danh sách. Chạm \"+ Trích dẫn\", viết câu và chọn sách trong Góc đọc sách, hoặc gõ tên khác bằng \"✏️ Khác\"; tác giả không bắt buộc. ✏️ sửa trích dẫn và 🗑️ xóa. Trích dẫn là những thẻ đánh dấu sách để vuốt qua – 🎨 ở trên đổi sang ảnh hoặc bức tường thẻ.",
    faq_a_room_wish_jar: "Trên kệ trong căn phòng bí mật có một chiếc hũ thủy tinh đựng ước mơ. Chạm vào chiếc hũ nhỏ trên kệ trên cùng (hoặc Kệ > Hũ điều ước) và viết bạn muốn cuộc sống của mình trông như thế nào – bay bổng tùy thích, không đúng không sai. Mỗi điều ước được gấp thành một mẩu giấy và rơi vào hũ. “Rút một mẩu giấy” mở ngẫu nhiên một mẩu, và mẩu nào cũng có thể mở riêng. Từ lần thứ hai mở cùng một điều ước, bạn có thể biến nó thành mục tiêu và chia thành từng bước nhỏ. Mỗi tuần một lần, một mẩu giấy với một điều ước của bạn sẽ nhẹ nhàng hiện lên – không áp lực, chỉ để nhắc bạn đang hướng về đâu.",
    faq_q_book_quotes: "Lưu trích dẫn từ những cuốn sách tôi yêu thích ở đâu?",
