    faq_a_saved_meals_page: "Các bữa ăn đã lưu có trang riêng: Dinh Dưỡng & Chỉ Số > ⭐ Bữa ăn đã lưu (hoặc ⭐ trong menu). Ô tìm kiếm ở trên tìm bữa ăn theo tên hoặc nguyên liệu, \"Dùng gần đây\" hiện những gì bạn mới thêm, còn các thẻ (Bữa sáng, Bữa trưa, Bữa tối, Súp…) hiện từng bữa trong ngày. \"+ Hôm nay\" thêm bữa ăn vào Theo Dõi Bữa Ăn Hàng Ngày của hôm nay, ở ô trống tiếp theo. Chạm vào một bữa để sửa hoặc xóa, và ＋ ở trên để thêm bữa mới.",
