    presets_tab_sweet: "Đồ ngọt",
    faq_a_notes_sticky_look: "Ghi chú là một danh sách ngắn các thẻ kính – 🎨 ở đầu Ghi chú đổi kiểu hiển thị của toàn bộ Ghi chú: danh sách, các nút ngày ở trên và cửa sổ viết ghi chú – kính, danh sách gọn, thẻ ghi hoặc băng dính washi. Ghi chú đang được kéo vẫn giữ nguyên kiểu và màu của chính nó. Chạm vào chữ của ghi chú để mở – ở đó bạn có thể sửa, đổi màu và xem lần cuối viết là khi nào. Chạm ○ khi đã xong, còn × sẽ chuyển nó vào lưu trữ (🗑️ ở cuối danh sách để lấy lại). Kéo bằng ⠿ để đổi thứ tự, đưa xuống dưới “Để sau”, hoặc thả vào một ngày ở trên. ! đánh dấu ghi chú là gấp – ghi chú nhẹ nhàng trượt lên những hàng đầu tiên với một nhãn nhỏ “Gấp”; chạm thêm lần nữa để bỏ đánh dấu.",
    faq_q_notes_sticky_look: "Làm sao để mở, sửa hoặc xóa một ghi chú?",
    note_to_archive_btn: "Chuyển vào lưu trữ",
    faq_a_routine_clash: "Nếu vào giờ đó, trong cùng những ngày, đã có một mục, sẽ có hai lựa chọn: \"Thay thế\" – mục mới lấy giờ đó và bạn chọn giờ khác cho mục cũ (khi sửa một mục có sẵn, giờ trước đó của nó được gợi ý, nên hai mục chỉ việc đổi chỗ), hoặc \"Cả hai\" – cả hai cùng ở một giờ, mục này dưới mục kia. Nếu ngày khác nhau (ví dụ một mục Chủ nhật–Thứ năm, mục kia Thứ sáu) thì không hỏi gì cả.",
    faq_q_routine_clash: "Chuyện gì xảy ra khi đặt một mục trong thói quen vào giờ đã có mục khác?",
    routine_clash_both: "✌️ Cả hai – cả hai lúc {time}",
    routine_clash_move_btn: "Chuyển và lưu",
    routine_clash_move_to: "Chuyển \"{title}\" sang mấy giờ?",
    routine_clash_replace: "🔄 Thay thế – và chuyển \"{title}\" sang giờ khác",
    routine_clash_title: "Lúc {time} đã có: {title}",
    faq_a_new_me_coffee: "Bên dưới thực đơn hôm nay có một phần tóm tắt ngắn: tất cả các bữa trong ngày cộng lại bao nhiêu calo, còn bao nhiêu cho cà phê và đồ uống, cùng các nút cho cà phê và đồ uống đã chọn – chạm một lần là thêm vào Đồ uống. Trong “Chọn tối đa 3 thứ bạn thích” bên dưới các nút (và trong bảng câu hỏi), chọn những gì sẽ hiện: nước lọc / nước có ga, trà thảo mộc, đồ uống ăn kiêng, đen / americano (~5), trà với chút sữa (~25), cà phê pha với nước và tối đa 100 ml sữa hoặc sữa thực vật (~50), ca cao nóng nhẹ, sữa ấm hoặc cà phê thường / latte (~120).",
    faq_q_new_me_coffee: "Thêm cà phê ở đâu, và làm sao biết hôm nay còn bao nhiêu?",
