    nm_late_ideas: "Ví dụ: {ideas}",
    nm_late_ideas_none: "Hôm nay còn rất ít – trà, nước hoặc cà phê đen",
    nm_late_room_line: "Chút gì nhỏ trước khi ngủ · hôm nay còn ~{n} kcal",
    faq_a_recipe_examples: "Bên dưới công thức của riêng bạn có các công thức mẫu: bữa sáng, salad, súp, món chính, món phụ, món ăn vặt, tráng miệng và món thuần chay, mỗi món có thời gian chuẩn bị, calo mỗi khẩu phần và một khẩu phần nặng bao nhiêu gam. Chạm vào công thức để mở, và \"Lưu vào Công Thức Của Tôi\" tạo một bản sao của riêng bạn để sửa. Các nhãn danh mục dùng để lọc, chạm lại vào cùng nhãn sẽ hiện tất cả.",
    faq_a_recipe_grams: "Trong công thức, cạnh lượng calo có ghi \"1 khẩu phần ≈ X g\". Với công thức của bạn, hãy điền \"Số gam mỗi khẩu phần\" (và thời gian chuẩn bị nếu muốn) trong biểu mẫu công thức: cả hai đều không bắt buộc, và thời gian hiện trên dải màu của công thức.",
