    faq_a_recipe_scan_multi: "Có. Trong \"Thêm Công Thức\", chạm 📷 và chọn một hoặc nhiều ảnh (tối đa 6; PDF cũng được). Mỗi ảnh hiện trong một danh sách ngắn để chọn nội dung: Tất cả, Nguyên liệu hoặc Cách làm, và \"➕ Thêm ảnh\" để thêm nữa. Sau đó chạm \"✨ Quét công thức\": AI ghép tất cả thành một công thức, đúng thứ tự và không lặp dòng, và chỉ tính là một lần quét. Nhiều ảnh chọn từ 📷 Ảnh trong trợ lý AI cũng mở ở đây.",
    faq_q_recipe_scan_multi: "Có thể quét một công thức từ nhiều ảnh không, ví dụ nguyên liệu và cách làm chụp riêng, hoặc hai trang?",
