    recipe_scan_too_many: "Tối đa {n} ảnh cho mỗi công thức",
    faq_a_note_written_at: "Chạm vào chữ của ghi chú để mở. Bên trong, dưới phần chữ, sẽ hiện lần cuối ghi chú được viết, với ngày và giờ chính xác. Chỉ khi sửa chính phần chữ thì mới cập nhật: lưu trữ rồi khôi phục, đánh dấu ✓, màu sắc hay di chuyển ghi chú đều không làm thay đổi.",
