    note_written_at: "Viết lần cuối: {date}",
    faq_a_new_me_month: "Trong ba lô kỳ diệu → Lịch tháng: mỗi ngày được tô màu theo số bữa đã đánh dấu, mũi tên ‹ › chuyển giữa các tháng, và bên dưới lịch có calo trung bình mỗi ngày của tháng. Chạm vào một ngày sẽ thấy hôm đó đánh dấu bao nhiêu bữa và ăn bao nhiêu calo.",
