    nm_month_day_line: "Bữa đã đánh dấu: {checks} · calo: {kcal}",
    nm_extra_line_small: "Thêm {n} calo cho bữa này, từ bữa sáng nhỏ – ví dụ {ideas}",
    faq_a_new_me_small_breakfast: "Một bữa sáng nhẹ (khoảng 170 kcal): bánh pita spelt (tối đa 100 kcal) với đồ phết hoặc phô mai, kèm một loại rau – chọn tối đa 3 thứ bạn thích, ví dụ 1 muỗng cà phê sô-cô-la phết bánh, 1 muỗng cà phê bơ đậu phộng hoặc một lát phô mai cứng (tối đa 22% chất béo). Vì bữa này nhỏ, “Thêm một bữa nhỏ” sẽ đi kèm vào một giờ khác (ví dụ một tiếng rưỡi sau, 11:30 → 13:00 – có thể chọn giờ khác): thêm một pita & đồ phết, sữa chua protein & trái cây, bánh gạo & phô mai, ngũ cốc & sữa hoặc nửa pita & trứng – tối đa khoảng 200 kcal, có ✓ riêng. Phần vẫn còn dư được chia cho các bữa khác, và mỗi bữa cho thấy được thêm bao nhiêu, nên tổng cả ngày vẫn đúng kế hoạch. Có thể chọn trong bảng câu hỏi, hoặc đổi sang nó chỉ hôm nay bằng 🔄 – ví dụ khi ăn sáng muộn.",
    faq_q_new_me_small_breakfast: "“Bữa sáng nhỏ” trong thực đơn New Me là gì?",
