    weather_sky_storm: "Giông bão",
    faq_a_ai_icon: "Có – trong Cài đặt > Giao Diện & Hiển Thị. Bong bóng mềm là mặc định, và với Premium bạn còn có thể chọn bộ não lơ lửng hoặc robot.",
    faq_a_new_me_favorites: "Có. Trong bảng câu hỏi (và khi làm lại từ cài đặt), bạn có thể chọn tối đa 2 lựa chọn cho mỗi bữa. Lựa chọn đầu tiên hiện trong thực đơn, bên dưới có dòng “hoặc” cho lựa chọn thứ hai – chạm vào sẽ đổi sang nó chỉ trong hôm nay. Và nếu bữa sáng chưa ăn đúng giờ, “⏰ Lát nữa” sẽ dời nó sang muộn hơn trong ngày, không thay đổi lượng calo.",
    faq_a_theme_mode: "Một số chủ đề đặc biệt đẹp nhất ở chế độ tối – Màu nước, Cực quang, Barbie và hai chủ đề lấp lánh – nên chọn một trong số đó sẽ chuyển ứng dụng sang chế độ tối, còn chọn bất kỳ chủ đề nào khác (kể cả tên lửa) sẽ chuyển sang sáng. Đen và Xám đậm vẫn giữ tối. Bạn luôn có thể đổi lại sau bằng 🌙 trong menu hoặc Chế Độ Sáng trong cài đặt.",
    faq_a_water_month: "Trong mục theo dõi nước. Mỗi mục trong ghi nhận hôm nay đều hiện giờ được thêm vào, và \"Bảng theo tháng\" mở cả tháng: mỗi ngày hiện đã uống bao nhiêu lít (✓ khi đạt mục tiêu ngày), và chạm vào một ngày sẽ hiện các mục của ngày đó kèm giờ.",
    faq_q_ai_icon: "Có thể đổi biểu tượng trợ lý AI không?",
