    dev_sim_panel_title: "PM – chỉ dành cho bạn",
    faq_a_new_me_weight_optional: "Không. Cả cân nặng hiện tại lẫn cân nặng mục tiêu trong bảng câu hỏi đều không bắt buộc. Nếu sau này thêm một lần cân (⚖️ Cân nặng trong “Hành trình của tôi” ở New Me, hoặc trong theo dõi cân nặng), tiến độ được tính từ lần cân đầu tiên.",
    faq_q_new_me_weight_optional: "Có bắt buộc nhập cân nặng trong New Me không?",
    nm_unlock_desc: "Thực đơn, thử thách và hành trình đã sẵn sàng – từng bước một, cùng nhau.",
    nm_unlock_title: "New Me đã được mở khóa!",
    room_reveal_star: "Một ngôi sao mới vừa sáng lên trong kính thiên văn trên sân thượng ✨",
    faq_a_room_records: "Máy hát đĩa có trong phòng ngay từ đầu, trên gốc cây cạnh ghế bành. Các đĩa của nó mở video chính thức của những bản hit lớn vài năm gần đây trên YouTube, và bên dưới có năm giai điệu êm dịu phát ngay trong phòng – đĩa quay khi nhạc phát, và “⏹ Dừng” tắt nhạc.",
    faq_a_room_roof_gifts: "Chúng đến cùng chìa khóa thứ 8. Chạm vào kính thiên văn để nhìn qua nó: bầu trời đêm ở thật gần – kéo (hoặc dùng các mũi tên) để nhìn xung quanh – và các thử thách đã hoàn thành vẽ nên trong đó một chòm sao, mỗi thử thách một ngôi sao; chạm vào một ngôi sao để xem đó là thử thách nào. Chạm vào chiếc rương nhỏ để mở nó – hiện tại bên trong còn trống – và chạm thêm một lần nữa để đóng lại.",
    faq_q_room_records: "Máy hát đĩa trong căn phòng bí mật có gì?",
    faq_q_room_roof_gifts: "Kính thiên văn và chiếc rương trên sân thượng là gì?",
    room_chest_letter: "Một lá thư nhỏ cho bạn",
    room_chest_letter_1: "Mỗi bước nhỏ trên con đường đều là thật – và bước nào cũng có ý nghĩa.",
    room_chest_letter_2: "Đối xử dịu dàng với bản thân là một phần của con đường, không phải là dừng lại.",
    room_chest_letter_3: "Có những ngày nhẹ nhàng hơn và có ngày nặng nề hơn. Vẫn có mặt trong cả hai mới là sức mạnh thật sự.",
