    faq_a_new_me_preview: "Có. Trang New Me mở đầu bằng một video ngắn về những gì diễn ra bên trong: bảng câu hỏi, những ngọn đèn trong hành lang, ba lô, các thử thách và chìa khóa. Bên dưới là mọi thứ được bao gồm, một ngày mẫu và những câu trả lời ngắn.",
    faq_q_new_me_preview: "Có thể xem New Me trước khi mua không?",
