    nm_trailer_replay: "Xem lại",
    ai_chat_food_edit: "✏️ Sửa calo / đạm",
    ai_chat_food_invalid: "Calo phải là số lớn hơn 0",
    ai_chat_food_updated: "Đã cập nhật:",
    faq_a_ai_chat_food_fix: "Có. Bên dưới câu trả lời trong cuộc trò chuyện, chạm ✏️ Sửa calo / đạm, đổi số rồi chạm Lưu. Chỉ phần vừa thêm thay đổi – kể cả khi nó đã được gộp vào một bữa phụ có sẵn. AI có thể sai, nên xem lại nhanh một chút là tốt.",
    faq_a_new_me_home_btn: "Nếu bạn có New Me, một 💎 nhỏ cạnh chế độ tập trung ở đầu màn hình chính sẽ mở thực đơn hôm nay. Các bữa ăn hôm nay cũng hiện trong Ngày Của Tôi, mỗi bữa có một ✓.",
    faq_a_routine_item_days: "Có. Chạm vào mục trong Thói Quen Của Tôi và chọn ngày của nó ở 📅 Ngày – ví dụ chỉ từ thứ Hai đến thứ Sáu. Những ngày khác nó không hiện trong Ngày Của Tôi và không có ✓; trong Thói Quen Của Tôi nó vẫn ở đó, mờ hơn, kèm các ngày bên cạnh. Thẻ hỏi về một mục sau 3 ngày không có ✓ cũng chỉ đếm các ngày của mục đó.",
    faq_q_ai_chat_food_fix: "Có thể sửa calo hoặc đạm sau khi trợ lý ghi món ăn không?",
    faq_q_new_me_home_btn: "New Me nằm ở đâu trên màn hình chính?",
    faq_q_routine_item_days: "Một mục trong Thói Quen Của Tôi có thể chỉ vào vài ngày nhất định không?",
    routine_item_days_label: "📅 Ngày",
    home_note_meal_ph: "Tìm bữa ăn đã lưu…",
    menu_quick_search: "Tìm nhanh",
    nm_times_hint: "Mẹo: bạn có thể đặt giờ muộn nhất mà bạn thường ăn mỗi bữa – ví dụ 9:00 nếu bạn hay ăn khoảng 8 giờ.",
    room_game_marquee: "Trên đường đi – dừng lại để tận hưởng",
    room_sand_erase_aria: "Chà để xóa chữ",
    faq_a_home_note_line: "Viết vào dòng ở giữa màn hình chính rồi chạm ➤ (hoặc Enter) – ghi chú được lưu vào Ghi Chú. Chạm 📝 ở đầu dòng, nó đổi thành 🛒: khi đó điều bạn viết sẽ vào Danh Sách Mua Sắm. Chạm thêm lần nữa để thành 🍎: gõ vài chữ, các bữa ăn đã lưu phù hợp sẽ hiện ra, chạm một cái là ghi vào bữa ăn hôm nay. Với 🎤 bạn chỉ cần nói ra.",
    faq_a_night_mode: "Mở menu ☰ và chạm 🌙 ở trên cùng – cả ứng dụng chuyển sang tối. ☀️ ở cùng chỗ sẽ đưa ban ngày trở lại. Cũng có trong Cài Đặt, mục Chế Độ Sáng.",
    faq_q_home_note_line: "Làm sao viết ghi chú nhanh từ màn hình chính?",
    faq_q_night_mode: "Làm sao chuyển sang chế độ ban đêm?",
    menu_day_mode: "Chế độ ban ngày",
    menu_night_mode: "Chế độ ban đêm",
    faq_a_secret_room_yoga: "Cuối lối mòn trong rừng có một cánh cổng phát sáng, phía sau, cạnh một thác nước, các sinh vật của khu rừng – Lumi, Puffi, Nixie và Sparklet – ngồi trên thảm của mình thành nửa vòng tròn, và Flora, cô giáo yoga, ngồi đối diện chúng trên tấm thảm duy nhất đặt trên tảng đá. Chạm vào Flora: cô mở mắt, mọi thứ xích lại gần, và cuộc trò chuyện bắt đầu chậm rãi, có thời gian để đọc – Flora hỏi thăm mọi người, mỗi sinh vật trả lời bằng chính tên mình (cạnh mỗi dòng có hình vẽ nhỏ của người đang nói), rồi cô hỏi bạn cảm thấy thế nào khi ở bên những người thân thiết. Cuộc trò chuyện đi tiếp theo câu trả lời của bạn – người tốt, một người khó gần, hay chút cô đơn. Mỗi con đường kết thúc bằng một nhiệm vụ nhỏ (có thể thêm ngay vào Ngày Của Tôi; khi nhiệm vụ là viết điều gì đó, sẽ có chỗ để viết, và nội dung được lưu vào cuốn nhật ký kỳ diệu) và một tư thế với ba hơi thở cùng nhau. ↩ lùi lại một bước, ✦ bắt đầu cuộc trò chuyện mới. Chiếc chìa khóa tiếp theo mở thác nước: ngồi lên tảng đá thì mọi thứ biến mất, chỉ còn tiếng nước. Khi cúi xuống mặt hồ, một câu hỏi hiện lên từ làn nước – con người thật của bạn sẽ làm gì hôm nay? – và câu trả lời trở thành một việc nhỏ trong Ngày Của Tôi. Đây là một khoảnh khắc dịu dàng, không thay thế cho việc trò chuyện với chuyên gia.",
    faq_q_secret_room_yoga: "Ở yoga trong rừng có gì?",
    room_back_to_forest: "Về lối mòn",
    room_back_to_yoga: "Về lớp yoga",
