    yg_g_good_msg: "Người tốt đáng được nghe rằng họ tốt. Một lời cảm ơn nhỏ có thể làm nên cả ngày của họ.",
    yg_g_hard: "Cảm ơn bạn đã nói ra. Điều gì làm bạn nặng lòng nhất?",
    yg_g_listen: "Không được lắng nghe thật mệt. Tiếng nói của bạn quan trọng, kể cả khi nó nhỏ nhẹ.",
    yg_g_new: "Người mới bắt đầu từ một lời chào nhỏ. Một lớp học, một buổi đi dạo, một nhóm – một bước.",
    yg_g_old: "Người đã biết bạn là một nơi ấm áp. Một tin nhắn ngắn là đủ.",
    yg_g_start: "Và giờ đến lượt bạn 🌿 Dạo này bạn cảm thấy thế nào khi ở bên những người thân thiết?",
    yg_g_used: "Khi ta cho đi mà không nhận lại gì, có điều gì đó bên trong mệt mỏi. Nhận ra điều đó là bình thường.",
