    nm_time_hour: "Giờ",
    nm_time_minutes: "Phút",
    routine_time_taken: "Giờ này đã có việc rồi: {title}",
    faq_a_new_me_times: "Trong bảng câu hỏi lúc đầu, và bất cứ lúc nào trong phần cài đặt New Me → “Giờ ăn”. Nếu thói quen của bạn đã có giờ ăn, giờ sẽ được lấy từ đó – và có thể ẩn các bữa trong thói quen, hiện các bữa New Me thay vào chỗ đó. Nếu chưa có, bạn chọn một ngày ăn mấy bữa (2 bữa chính + 1 bữa phụ / 2 bữa chính + bữa tối nhẹ / 2 bữa chính + 1 bữa phụ + bữa tối nhẹ) và mỗi bữa lúc nào. Với “2 bữa chính + 1 bữa phụ”, đó là bữa trưa lúc 11:30, bữa phụ lúc 16:00 và bữa tối lúc 19:00 (bữa nào cũng đổi được). Đây là giờ ăn của bạn ở mọi nơi: trong hành lang, trong Ngày Của Tôi, trong Thói Quen Của Tôi và trong lời nhắc. Chọn thế nào thì lượng calo trong ngày vẫn giữ nguyên: phần bị bỏ được chia cho các bữa còn lại.",
    faq_q_new_me_times: "Làm sao đặt giờ ăn trong New Me?",
    nm_times_count: "Một ngày ăn mấy bữa?",
    nm_times_from_routine: "Có, lấy từ thói quen",
    nm_times_hide: "Ẩn các bữa trong thói quen của tôi và hiện các bữa New Me thay vào đó",
    nm_times_later: "Để sau",
    nm_times_manual: "Không, chọn ở đây",
    nm_times_none_found: "Thói quen của bạn chưa có bữa ăn nào – hãy chọn ở đây ăn mấy bữa và lúc nào.",
    nm_times_q: "Thói quen của bạn có giờ ăn cố định không?",
    nm_times_saved: "Đã lưu giờ ăn",
    nm_times_title: "Giờ ăn",
    faq_a_routine_exact_time: "Có. Khi mô tả thói quen cho AI với giờ chính xác (như \"16:10 giao dịch\"), giờ đó được lưu đúng như vậy – không làm tròn thành giờ chẵn. Mọi thứ ghi trong thói quen luôn hiện trên bảng, kể cả khi giờ đó chưa được chọn trong phần cài đặt giờ, và khi bỏ một giờ đang có nội dung, ứng dụng sẽ hỏi trước. Bạn cũng có thể đổi giờ bằng tay: chạm vào giờ trong cửa sổ của mục rồi chọn giờ và phút.",
    faq_q_routine_exact_time: "Thói quen của tôi có thể có giờ chính xác, như 16:10 không?",
