    routine_daysoff_which: "Những ngày nào?",
    faq_a_secret_room_diary: "Chỉ mình bạn. Các trang nhật ký được lưu trong tài khoản của bạn, nên có trên mọi thiết bị, và không ai khác thấy được. Cuốn nhật ký kỳ diệu trên bàn trong căn phòng bí mật sẽ mở nó, cuốn nhật ký ở góc âm nhạc cũng vậy. Bên dưới trang mới có một bảng tháng gập lại: dấu chấm đánh dấu mỗi ngày có trang viết, và chạm vào một ngày sẽ mở các trang của ngày đó – ở đó cũng có thể xóa trang. Khi cuốn nhật ký đã mở, bạn cũng có thể thêm nó vào menu chính – bằng công tắc trong chính cuốn nhật ký hoặc trong cài đặt của New Me.",
    faq_a_secret_room_places: "Mỗi lối vào ở cổng rừng mở bằng chìa khóa riêng. Phía sau là: hiên nhà nhìn ra biển (trên chiếc bàn nhỏ là cây đèn thần Aladdin – chạm một cái là một tinh linh rừng bay lên từ đó trong làn sương kỳ diệu, xoay vòng quanh và bắt đầu cuộc trò chuyện về điều ước của bạn – xem “Tinh linh trong đèn thần làm gì?”), cây đàn và cuốn nhật ký (cây đàn chơi một giai điệu ngắn, êm dịu rồi tự dừng, còn từng chiếc trong ba đĩa than treo trên cây chơi một giai điệu kỳ diệu của riêng mình – chạm lần nữa để dừng – còn cuốn nhật ký trên gốc cây là để viết), căn phòng hít thở (một hồ nước yên tĩnh lúc hoàng hôn – trên mặt nước có một chiếc đèn lồng sen nổi: chạm vào, viết một điều ước, và nó trôi đi cùng điều ước, xa tít vào giữa hồ; với đũa thần, bạn có thể viết lên cát điều muốn buông bỏ, và chữ sẽ ở đó cho đến khi bạn lấy ngón tay xóa đi) và lối mòn trong rừng (lối mòn mở ra vào ban đêm, và chạm vào đèn lồng để chuyển sang ban ngày; từ cành cây lớn treo một chiếc xích đu kỳ diệu, băng ghế để ngồi, và chạm vào tấm biển để xem gần – một tấm bảng có sáu câu hỏi nhỏ để đánh dấu). Trên lối vào bị khóa có ghi còn bao nhiêu chìa khóa. Cuối lối mòn, một cánh cổng phát sáng dẫn đến lớp yoga cạnh thác nước – và từ đó, đến chính thác nước.",
    faq_q_secret_room_diary: "Ai nhìn thấy cuốn nhật ký?",
    faq_q_secret_room_places: "Sau những cánh cửa ở hành lang có gì?",
