    dictation_btn_aria: "Nói là thành chữ",
    dictation_mic_denied: "Micro đang bị chặn – hãy cho phép ở 🔒 cạnh địa chỉ trong trình duyệt, hoặc trong cài đặt điện thoại",
    faq_a_dictation: "Có – chạm vào micro 🎤 ở góc ghi chú nhanh hoặc trang viết trong sổ, rồi nói: chữ hiện ra ngay khi bạn nói, bằng ngôn ngữ của ứng dụng. Chạm lần nữa để dừng. Lần đầu, trình duyệt sẽ xin quyền dùng micro. Dùng được trên Chrome / Android và Safari trên iPhone. Trên máy tính cần có micro và trình duyệt như Chrome, Edge hoặc Safari – nếu thiếu gì, thông báo sẽ nói rõ là gì.",
    faq_q_dictation: "Có thể nói thay vì gõ không?",
    faq_a_secret_room: "Một căn phòng chỉ của riêng bạn, bên trong New Me – một ngôi nhà bên trong cây khổng lồ. Mỗi lần bạn thấy một bức tường và xoay bằng mũi tên (hoặc vuốt). Chìa khóa đầu tiên đến sau khi có ✓ cho một bữa ăn vào 3 ngày khác nhau và mở cửa – cùng cả căn phòng: máy tính, trò chơi, máy hát đĩa, kệ có thư viện bên trong và chú mèo. Sau đó, mỗi thử thách hoàn thành (cả thử thách của tuần) cho một chìa khóa mở nơi tiếp theo: sân thượng sao, hiên nhà nhìn ra biển, cây đàn và cuốn nhật ký, căn phòng hít thở, lối mòn trong rừng có yoga, thác nước và một bất ngờ trên sân thượng – và thử thách thứ 8 mang đến một chiếc chai từ biển, bên trong là lá thư từ quá khứ. Khi có gì đó mở ra, một mũi tên chỉ đường. Cánh cửa nhỏ ở phía dưới máy chơi game cũng mở ra – hiện tại chiếc tủ phía sau còn trống. Trên sân thượng sao, ngôi sao được chạm sẽ rơi như sao băng, còn chú mèo ngồi trên chiếc đệm.",
