    room_wall_window_title: "Cửa sổ và máy tính",
    faq_a_steps_in_sport: "Ở trên cùng của Theo Dõi Tập Luyện, trong một dải nhỏ: số bước hôm nay và tuần này. Số bước sẽ được đếm tự động khi ứng dụng kết nối với Google Fit / Apple Health trong phiên bản ứng dụng điện thoại – nút 🔗 bên cạnh sẽ giải thích.",
    faq_q_steps_in_sport: "Bộ đếm bước chân hàng ngày ở đâu?",
    sport_steps_today_label: "bước hôm nay",
    sport_steps_week_label: "tuần này",
    faq_a_reminders_one_place: "Mỗi lời nhắc chỉ đến một lần, ở một nơi. Nếu ứng dụng đang mở trước mặt bạn (trên máy tính, iPad hoặc điện thoại), lời nhắc hiện ở đó; nếu không, nó đến dưới dạng thông báo chỉ trên điện thoại. Bấm '✅ Đã xong, cảm ơn!' hoặc 'Đã hiểu!' ở bất kỳ đâu sẽ đóng nó trên mọi thiết bị, và nó không quay lại. 'Chưa xong' sẽ hoãn lại: lời nhắc quay lại mỗi 5 phút, mỗi lần chỉ ở một nơi. Đánh dấu ✓ cho việc trong danh sách cũng được tính là đã xong. Để nhận thông báo cả trên máy tính và máy tính bảng, hãy bật 'Cả trên máy tính và máy tính bảng' trong Cài Đặt > Thông Báo.",
    faq_q_reminders_one_place: "Tại sao lời nhắc chỉ đến một lần, và chỉ đến điện thoại?",
    reminder_all_devices_hint: "Mặc định mỗi lời nhắc chỉ đến một lần, ở một nơi: điện thoại, hoặc thiết bị đang mở ứng dụng ngay trước mặt bạn. Bấm Đã xong hoặc Đã hiểu ở một nơi sẽ đóng nó ở mọi nơi.",
    reminder_all_devices_label: "Cả trên máy tính và máy tính bảng",
    myday_water_info: "8 ly nước vừa / nhỏ trung bình khoảng 2 lít",
    faq_a_good_things: "Buổi tối (từ 18:00) một nút nhỏ hiện dưới ngày tháng: viết tối đa 3 điều tốt đẹp đã xảy ra hôm nay – chỉ một thôi cũng đủ. Chúng được lưu lại, và trong 'Những ngày trước' bạn xem được những gì đã viết. 'Không phải tối nay' ẩn nút đến ngày mai, và bạn có thể tắt hẳn trong Cài đặt > Cá Nhân Hóa & Lịch.",
    faq_a_home_countdown: "Đánh dấu ⭐ cho một sự kiện trong lịch (ngôi sao bên cạnh trong danh sách sự kiện). Sự kiện có sao gần nhất trong 100 ngày tới hiện dưới ngày tháng – 'Còn 3 ngày · Sinh nhật mẹ', 'Ngày mai · …' hoặc 'Hôm nay · …'. Chạm vào để đến ngày đó trong lịch.",
    faq_a_home_streak: "Nó đếm bạn đã có bao nhiêu ngày liên tiếp với ít nhất một ✓ – bất cứ điều gì trong Ngày Của Tôi, Thói Quen Của Tôi, Mục Tiêu Của Tôi hoặc New Me. Hiện từ 2 ngày trở lên. Nếu hôm nay chưa có ✓, chuỗi vẫn chưa đứt – vẫn còn cả ngày. Và nếu chuỗi kết thúc, nó chỉ lặng lẽ biến mất, không trách móc.",
    faq_a_home_weather: "Bật 'Thời tiết trên bầu trời màn hình chính' trong Cài đặt > Cá Nhân Hóa & Lịch và cho phép vị trí. Khi đó bầu trời màn hình chính hiển thị thời tiết thật nơi bạn ở – mặt trời (ban đêm là trăng và sao), mây, mưa, tuyết, giông hoặc sương mù – ở mọi chủ đề, cập nhật khoảng mỗi 40 phút. Vị trí ước chừng (làm tròn khoảng 1 km) chỉ lưu trên thiết bị của bạn và được kiểm tra qua máy chủ của chúng tôi với MET Norway. Mặc định đang tắt. Bên dưới công tắc có ghi thời tiết bên ngoài lúc này – ví dụ ⛅ Có mây rải rác, vì vậy bầu trời có cả mặt trời lẫn mây.",
    faq_q_good_things: "'3 điều tốt đẹp hôm nay' là gì?",
    faq_q_home_countdown: "Làm sao có đếm ngược trên màn hình chính?",
