    settings_good_things_label: "\"3 điều tốt đẹp\" vào buổi tối",
    settings_weather_hint: "Mưa, mây hoặc tuyết trên nền màn hình chính, theo thời tiết nơi bạn ở. Vị trí ước chừng chỉ lưu trên thiết bị này và được kiểm tra qua máy chủ của chúng tôi với MET Norway.",
    settings_weather_label: "Thời tiết trên bầu trời màn hình chính",
    weather_failed: "Hiện chưa kiểm tra được thời tiết.",
    weather_location_denied: "Không có quyền truy cập vị trí – hãy cho phép trong cài đặt trình duyệt rồi thử lại.",
    faq_a_home_focus: "Chạm ◎ ở trên cùng màn hình Trang chủ: mọi thứ biến mất trừ một việc của lúc này – việc diễn ra vào giờ này, hoặc việc tiếp theo trong danh sách hôm nay – với một ✓ lớn, và Ghi Chú Nhanh. Sau khi ✓, việc tiếp theo hiện ra. Chạm 'Chế độ tập trung ✕' ở trên để mọi thứ quay lại.",
    faq_a_home_search: "Mở menu ☰ – ô tìm kiếm nằm ngay trên cùng. Gõ ít nhất 2 chữ: kết quả lấy từ ghi chú, danh sách mua sắm, lịch, công thức, sổ tay (tiêu đề và chữ trong trang), mục tiêu, bảng và sách của bạn, nhóm theo loại – chạm vào một kết quả để đi thẳng đến đó.",
    faq_a_my_day: "Ngày Của Tôi gộp những gì trước đây là Thoáng Nhìn Ngày Hôm Nay và Thói Quen Của Tôi vào một dòng thời gian. Ở cuối màn hình Trang chủ bạn thấy đã xong bao nhiêu, việc bây giờ hoặc tiếp theo (kèm ✓ nhanh), và cạnh tiêu đề là một ly nước với +1. Chạm vào (hoặc vuốt lên) để mở cả ngày: trên cùng là những việc không có giờ, rồi tất cả theo giờ – việc, sự kiện và cuộc họp trong lịch, các khung giờ cố định hằng tuần, thói quen hôm nay, các bước nhỏ của mục tiêu và bữa ăn New Me – cùng một vạch cho bây giờ. Lọc theo Việc cần làm, Thói quen hoặc Cuộc họp & sự kiện. ✓ ở đây cũng là ✓ ở mọi nơi khác (Thói Quen Của Tôi, Mục Tiêu Của Tôi, lịch) và làm nở một bông cúc ở góc. 'Sửa thói quen' mở Thói Quen Của Tôi (cũng có trong menu), còn '＋ Thêm cho hôm nay' thêm một việc cho hôm nay. Chạm vào tiêu đề \"Ngày Của Tôi\" (hoặc thanh nhỏ phía trên) sẽ đóng lại.",
