    faq_a_goal_small_steps: "Mỗi mục tiêu trong Mục Tiêu Của Tôi là một con đường: những cột mốc đã ở phía sau, viên đá hôm nay đang sáng và chiếc cúp ở cuối đường. Hãy đặt cho mục tiêu một bước nhỏ – mỗi ngày, hoặc mỗi tuần vào ngày bạn chọn – điều có thể làm ngay cả trong ngày khó khăn, như 'Chạy nhẹ 10 phút'. Tất cả bước nhỏ hôm nay hiện ở đầu Mục Tiêu Của Tôi và trong Ngày Của Tôi, mỗi bước có một ✓ nhanh, và '✓ Hôm nay đã làm' bên dưới con đường của mục tiêu sẽ tô đầy các chấm của 7 ngày qua. Ghi chú 'Trên đường đến 10 · không dừng lại' được giữ ở trên cùng có chủ ý: chúng ta không cần hoàn hảo – chỉ cần làm một chút mỗi ngày để tiến lên.",
