    faq_a_new_me_letter_gift: "Khi bắt đầu New Me (hoặc sau đó, trong màn hình Thử thách) có thể viết một lá thư gửi chính mình trong tương lai. Sau khi niêm phong, thư không thể đọc hay sửa cho đến khi được mở: trong chiếc chai từ biển ở căn phòng bí mật, hoặc khi hoàn thành cả 20 thử thách – nơi còn có một món quà đang chờ.",
    faq_q_new_me_letter_gift: "Lá thư từ quá khứ là gì?",
    faq_a_new_me_challenges: "🏆 Thử thách có 20 thử thách: 10 thử thách lớn (như 5 ngày không đường, một tuần không tinh bột, hay giảm 4 kg trong một tháng – mỗi ngày thâm hụt calo, tập luyện và không đường) và 10 thử thách nhỏ – thói quen nhỏ trong một tuần, như cà phê quế không đường. Khi chọn một thử thách sẽ có câu hỏi khi nào bắt đầu: hôm nay, ngày mai, tuần sau hoặc ngày khác. Một thử thách lớn và một thử thách nhỏ có thể chạy cùng lúc. Thử thách đang diễn ra hiện trên cùng thực đơn và trong Ngày Của Tôi, kèm ✓ cho ngày đó. Mỗi tuần thử thách có một ngày nghỉ (🍕) không làm đứt thử thách, và ngày không đánh dấu được tính là ngày nghỉ – có thể đánh dấu hôm nay và cả hôm qua. Một số ngày tự được đánh dấu: buổi tập 20 phút trong Theo Dõi Tập Luyện, hoặc các bữa trong thực đơn được ✓. Mỗi thử thách có một ⓘ cho biết chính xác những gì được tính (ví dụ danh sách đầy đủ các loại tinh bột) – ngay trong thử thách và bên cạnh nó trong Ngày Của Tôi. Bên dưới, 🌱 Phát triển bản thân có 48 thử thách nhỏ kéo dài một tuần (không tính vào con số 20) – xem “Thử thách của tuần là gì?”.",
