    nm_ch_completed_label: "thử thách đã hoàn thành",
    nm_tile_challenges: "Thử thách",
    faq_a_workout_calories: "Có. Mỗi buổi tập có ước tính lượng calo đã đốt – theo loại, thời lượng và cân nặng gần nhất (chạy và đạp xe còn theo tốc độ khi có nhập quãng đường). Con số hiện trong danh sách buổi tập và bản tóm tắt tháng (Đã đốt), và được cộng vào ngân sách calo của ngày đó: trong Theo Dõi Bữa Ăn Hàng Ngày, Chỉ Số Calo và Cân Nặng và vòng tròn của New Me. Đây là ước tính nên có dấu ~.",
    faq_q_workout_calories: "Tập luyện có được tính vào calo trong ngày không?",
    faq_a_new_me_flexible_menu: "Có. Trong bảng câu hỏi và phần cài đặt, chọn số bữa mỗi ngày – 2 bữa chính + 1 bữa phụ / 2 bữa chính + bữa tối nhẹ / 2 bữa chính + 1 bữa phụ + bữa tối nhẹ – và ➖ trên thẻ bữa ăn sẽ bỏ bữa đó (giữ lại ít nhất 3); ‘Thêm lại’ đưa nó trở lại. Dù thế nào, lượng calo trong ngày vẫn giữ nguyên: phần bị bỏ được chia cho các bữa còn lại, và dưới mỗi bữa có ghi được thêm bao nhiêu và có thể ăn kèm gì. ✏️ Sửa trên một bữa mở phần mô tả – đổi tùy ý (ví dụ bỏ bánh mì hoặc thêm một quả trứng) và AI tính lại calo và đạm. 🔄 Đổi gợi ý các lựa chọn trong thực đơn, ⭐ Đã lưu và ✨ Tự viết; mỗi thay đổi có thể chỉ cho hôm nay hoặc từ nay về sau. Cuối mục ‘Cả ngày’ có ➕ Thêm món ăn – ghi lại món đã ăn ngoài thực đơn, AI sẽ tính và cộng vào hôm nay (✕ để xóa).",
    faq_q_new_me_flexible_menu: "Có thể đổi số bữa trong New Me, hoặc ăn món của riêng mình không?",
