    faq_a_goal_tasks_peek: "Có ba loại: các nhiệm vụ hằng ngày của một thử thách theo ngày đang diễn ra (ví dụ 'Không ăn tinh bột') – chúng xuất hiện mỗi ngày cho đến khi thử thách hoàn thành, và đánh dấu ✓ ở đó cũng sẽ đánh dấu ngày đó trong mục tiêu (và ngược lại); 📅 các cột mốc của mục tiêu mà bạn đã lên lịch – vào đúng ngày của chúng, và cả trong lịch; và 👣 bước nhỏ của bất kỳ mục tiêu nào khác – đặt khi thêm hoặc sửa mục tiêu (mỗi ngày, hoặc mỗi tuần vào ngày bạn chọn). Đây là những bước giống như trong 'Những bước nhỏ hôm nay' ở đầu Mục Tiêu Của Tôi, mỗi bước kèm biểu tượng của mục tiêu. Một lần +1 được ghi lại trong ngày đó sẽ tự động đánh dấu bước nhỏ (cân nặng cũng vậy, khi bước nhỏ chính là việc cân).",
