    faq_a_goal_days_challenge: "Trong Mục Tiêu Của Tôi, nhấn ＋ (hoặc ví dụ có sẵn '🔥 8 ngày'), chọn '📆 Thử thách theo ngày', nhập số ngày và thêm những việc bạn làm mỗi ngày (vd: 'Đi bộ 30 phút', 'Ăn theo thực đơn của tôi'). Mỗi ngày, đánh dấu các nhiệm vụ của ngày đó bên dưới con đường của thử thách – khi tất cả đã được đánh dấu, ngày đó được tính, con đường tiến thêm một viên đá và chuỗi ngày 🔥 của bạn tăng lên (nếu không có nhiệm vụ hằng ngày thì chỉ có một nút '✓ Hôm nay tôi đã làm được'). Nút 🔁 cạnh một nhiệm vụ sẽ thêm nó vào Thói Quen Của Tôi vào giờ bạn chọn: đánh dấu ở đó cũng sẽ đánh dấu trong mục tiêu, và ngược lại. Các cột mốc của một mục tiêu thông thường cũng có thể được thêm vào Thói Quen Của Tôi theo cách tương tự.",
