    vision_focus_ribbon: "🎯 Mục tiêu của tháng",
    vision_tagline: "Mục tiêu lớn, từng bước nhỏ.",
    faq_a_app_tour: "Phần hướng dẫn tự mở một lần, khi bạn vào lần đầu. Nó bắt đầu bằng các phần của mình – chạm vào một phần để đi thẳng đến đó – rồi giới thiệu mọi phần của ứng dụng (màn hình chính, trợ lý AI và từng mục trong menu) và năm nhóm Cài đặt, mỗi nhóm kèm một lời giải thích ngắn, và ghé vào bên trong một số mục (ví dụ một lộ trình mục tiêu mẫu, chiếc túi và Google Calendar). Tiếp tục để đi tiếp, Quay lại để lùi lại, Bỏ qua phần này để sang phần kế tiếp, và ✕ để đóng hướng dẫn. Bạn có thể xem lại bất cứ lúc nào trong Cài Đặt > Trợ Giúp & Sử Dụng > Hướng dẫn ứng dụng, và tiếp tục từ chỗ đã dừng. Tiếp tục và Quay lại luôn ở cùng một chỗ phía dưới màn hình, và trên máy tính có thể dùng cả các phím mũi tên.",
    faq_q_app_tour: "Làm sao để xem lại hướng dẫn ứng dụng?",
    apptour_done_text: "Có câu hỏi? Trợ giúp & Câu hỏi thường gặp trong Cài Đặt giải đáp mọi thứ, và hướng dẫn này luôn có trong Trợ Giúp & Sử Dụng.",
    apptour_done_title: "Vậy là xong! 🎉",
    apptour_flow_recurring: "Trả góp & thanh toán định kỳ",
    apptour_flow_weight: "Cân nặng",
    apptour_flow_calories: "Calo hôm nay",
    apptour_flow_calendar: "Lịch",
    apptour_connect_text: "Việc làm ở một nơi sẽ tự động cập nhật những nơi khác:",
    apptour_connect_title: "Mọi thứ đều kết nối",
    apptour_s_support_text: "Trợ giúp & Câu hỏi thường gặp, liên hệ, chia sẻ ứng dụng – và hướng dẫn này, bất cứ lúc nào.",
    apptour_s_account_text: "Premium, mật khẩu, báo cáo cá nhân PDF, đồng bộ Google Calendar và xóa tài khoản.",
    apptour_s_notifications_text: "Thông báo nhắc nhở và âm thanh của chúng. Nút '⏰ Chưa xong' trên lời nhắc hoạt động như báo lại: cứ 5 phút lại nhắc một lần.",
    apptour_s_personalization_text: "Quốc gia, số bữa chính và bữa phụ mỗi ngày, ngày bắt đầu tháng tài chính, và những gì hiện trên màn hình chính.",
    apptour_s_appearance_text: "Ngôn ngữ, chế độ sáng hoặc tối, chủ đề, phông chữ, màu chữ, khả năng tiếp cận và kích thước hiển thị.",
    apptour_m_style_text: "Nút này chuyển menu sang ô lớn – và ngược lại. Màn hình chính chỉ hiện một trong hai.",
    apptour_m_style_title: "Danh sách hay ô",
