    apptour_m_calories_link: "Theo dõi cân nặng cũng ở đây – dùng chung với New Me và các mục tiêu cân nặng trong Mục Tiêu Của Tôi.",
    apptour_m_calories_text: "Thống kê calo theo ngày, tuần và tháng so với mục tiêu.",
    apptour_m_meals_link: "Bữa ăn đã lưu, danh sách món ăn và ước tính AI; New Me, thêm nhanh và đồ uống cũng được tính ở đây.",
    apptour_m_meals_text: "Ghi từng bữa ăn với calo và protein, ngày qua ngày.",
    apptour_m_recipes_link: "Quét công thức viết sẵn bằng 📷 Ảnh trong Trợ Lý AI.",
    apptour_m_recipes_text: "Công thức theo danh mục, kèm ảnh, calo và khẩu phần.",
    apptour_m_goal_link: "Có thể tự động theo dõi cân nặng hoặc số nhiệm vụ đã hoàn thành.",
    apptour_m_goal_text: "Một mục tiêu cho tháng, có thanh tiến độ và phần thưởng khi đạt được.",
    apptour_m_shopping_link: "Thêm món từ Ghi Chú Nhanh chỉ trong tích tắc.",
    apptour_m_shopping_text: "Danh sách mua sắm – đánh dấu món đồ ngay tại cửa hàng.",
    apptour_m_notes_link: "Kéo ghi chú vào Hôm Nay, Ngày Mai hoặc ngày khác để biến nó thành nhiệm vụ; ghi chú đã xóa nằm chờ trong 🗑️ Lưu trữ.",
    apptour_m_notes_text: "Ghi chú và ý tưởng trong một danh sách.",
    apptour_m_tables_link: "Trợ Lý AI có thể tự động thiết kế bảng.",
    apptour_m_tables_text: "Bảng cá nhân – quà tặng, phim bộ, danh sách – với cột văn bản, số, lựa chọn, ngày và ✓ (Premium).",
    apptour_m_study_link: "🪄 Phân Chia Thông Minh, trong thẻ ✅ Nhiệm vụ, chia một việc lớn thành các bước trên lịch.",
    apptour_m_study_text: "Túi của bạn: mỗi phần của cuộc sống một ngăn – bên trong có sổ, bảng và nhiệm vụ.",
    apptour_m_vision_link: "📅 trên một cột mốc sẽ đưa nó vào lịch; các bước nhỏ và nhiệm vụ của thử thách theo ngày hiện trong Ngày Của Tôi, và tiến độ cũng có thể theo một con số hoặc cân nặng của bạn.",
    apptour_m_vision_text: "Mục tiêu của bạn là những con đường từ các bước nhỏ – với bước hôm nay ở trên cùng. Cùng xem bên trong nhé 👇",
    apptour_m_myweek_link: "Đồng bộ với Google Calendar (trong Cài Đặt).",
    apptour_m_myweek_text: "Lịch tháng, công việc lặp lại hằng tuần có nhắc nhở, và mọi sự kiện có ngày cụ thể. Và một cuốn sổ giấy ghi các cuộc họp trong tuần 🤝.",
    apptour_m_newme_link: "Mọi thứ được tính vào Theo Dõi Bữa Ăn Hàng Ngày và Ngày Của Tôi; cân nặng dùng chung với Chỉ Số Calo và Cân Nặng.",
    apptour_m_newme_text: "Kế hoạch ăn uống 1.300 / 1.500 calo trong một thế giới trò chơi phép thuật: thực đơn hôm nay có ✓, đổi món theo ba cách – từ thực đơn, từ bữa ăn đã lưu, hoặc viết cho AI món đã ăn và AI tính calo – danh sách mua sắm, nhắc bữa ăn và hành trình tiến bộ với thành tích, số đo và ảnh. Thêm 🏆 20 thử thách – với một món quà ở cuối – và thử thách của tuần.",
    apptour_ai_table_text: "Mô tả bảng cần dùng – AI thiết kế các cột (Premium).",
    apptour_ai_photo_link: "Được lưu trong Công Thức Của Tôi.",
    apptour_ai_photo_text: "Chụp một công thức viết sẵn – AI điền giúp một công thức mới.",
    apptour_ai_schedule_link: "Chúng hiện trong lịch và trong Ngày Của Tôi.",
    apptour_ai_schedule_text: "Mô tả kế hoạch bằng lời thường, một lần hay lặp lại – chúng vào thẳng lịch.",
    apptour_ai_food_link: "Đi thẳng vào Theo Dõi Bữa Ăn Hàng Ngày và tổng của hôm nay.",
    apptour_ai_food_text: "Nhập món đã ăn – calo được ước tính và ghi lại giúp bạn.",
    apptour_newme_short_text: "Mở New Me – thực đơn hôm nay nằm ngay trên màn hình chính.",
    apptour_ai_link: "Huy hiệu nhỏ số 1 trên đó là lời nhắc hằng ngày 'điều quan trọng nhất hôm nay'.",
    apptour_ai_text: "Chỉ cần viết bằng lời đơn giản, trợ lý lo phần còn lại: ghi calo, đưa kế hoạch vào lịch, đọc công thức từ ảnh và tạo bảng.",
    apptour_quicknote_link: "📝 và 🛒 mở danh sách đầy đủ; 🍎 ghi một bữa ăn đã lưu vào Theo Dõi Bữa Ăn Hàng Ngày.",
    apptour_quicknote_text: "Ghi nhanh điều gì đó – vào Ghi Chú hoặc thẳng vào Danh Sách Mua Sắm.",
    apptour_routine_link: "Một thói quen có thể tự động ghi buổi tập vào Theo Dõi Tập Luyện.",
    apptour_routine_text: "Lịch sinh hoạt hằng ngày theo giờ, chia tab (con cái, học, công việc…). Đánh dấu ✓ mỗi ngày để xây dựng thói quen và chuỗi ngày; 📅 hiện cả tháng.",
    apptour_premium_text: "Mở khóa Trợ Lý AI đầy đủ, chủ đề, phông chữ, Túi của tôi và nhiều hơn nữa.",
    apptour_note_text: "Tờ giấy nhớ cho cả tuần. Bên trong, bánh răng ⚙ thêm danh sách đánh dấu 1–3 dòng và đổi màu, kiểu dáng.",
    apptour_peek_link: "Nhiệm vụ từ AI, lịch, các bước của mục tiêu và Google Calendar đều hiện ở đây – cùng lượng calo hôm nay 🔥 và 🎯 mục tiêu của tháng.",
    apptour_peek_text: "Mọi thứ của hôm nay ở một chỗ – việc cần làm, cuộc họp, thói quen và các bước nhỏ trên một dòng thời gian. Đánh dấu ✓ ngay tại đây.",
