    faq_a_receipts_total: "Trên màn hình Hóa Đơn / Biên Lai, chạm 🧮 'Tổng tất cả biên lai'. Chọn từ năm nào đến năm nào (mặc định từ biên lai cũ nhất đến năm nay), chạm Tính, và bạn sẽ thấy tổng của cả hai danh mục cộng lại - Chi phí gia đình và Chi phí kinh doanh - cùng số lượng biên lai và tổng của từng danh mục riêng.",
