    receipts_total_title: "Tổng tất cả biên lai",
    receipts_total_tile: "Tổng tất cả biên lai",
    faq_a_quick_note_apple: "🍎 bên cạnh 📝 và 🛒 trong cửa sổ ghi chú là lối tắt để nhanh chóng ghi một trong các bữa ăn đã lưu vào Theo Dõi Bữa Ăn Hàng Ngày của hôm nay. Mặc định nó được bật - nếu không cần, bạn có thể tắt trong Cài đặt > Cá Nhân Hóa & Lịch ('Hiện lối tắt 🍎 đến bữa ăn đã lưu trong cửa sổ ghi chú') và bật lại ở đó bất cứ lúc nào.",
    faq_q_quick_note_apple: "🍎 trong cửa sổ ghi chú là gì, và có thể ẩn nó không?",
    settings_quick_note_apple_label: "Hiện lối tắt 🍎 đến bữa ăn đã lưu trong cửa sổ ghi chú",
    faq_a_vision_board_today: "Trong Mục Tiêu Của Tôi, bên dưới con đường của một mục tiêu (trong 'Kế hoạch'), nhấn 📅 bên cạnh một cột mốc và chọn ngày. Bạn cũng có thể bật '🔁 Hằng tuần cho đến khi xong' – khi đó cột mốc sẽ lặp lại mỗi tuần vào cùng một ngày cho đến khi bạn đánh dấu một lần. Cột mốc sẽ xuất hiện vào ngày đó trong Ngày Của Tôi và trong lịch (và cả trong Google Calendar nếu đã kết nối), và nút sẽ cho biết cột mốc được lên lịch khi nào. Đánh dấu ✓ ở một nơi sẽ đánh dấu ở nơi kia và đưa con đường của mục tiêu tiến lên. Nhấn 📅 lần nữa để đổi ngày hoặc xóa khỏi lịch. Xóa một nhiệm vụ chỉ làm một lần khỏi lịch cũng sẽ xóa cột mốc đó khỏi mục tiêu; xóa một tuần của nhắc nhở hằng tuần chỉ xóa đúng tuần đó.",
    faq_q_vision_board_today: "Làm sao để đưa một cột mốc của mục tiêu vào lịch (📅)?",
    vision_milestone_already_today: "Bước này đã có trong nhiệm vụ hôm nay.",
