    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "Nhập tên đồ uống và lượng calo",
    nm_drink_more: "+ Thêm đồ uống",
    nm_drink_add: "Thêm",
    nm_drink_name_ph: "Đồ uống (vd: nước ép)",
    nm_drinks_hint: "Chỉ cần nhập tên đồ uống – lượng calo được tính tự động và có thể thay đổi con số.",
    nm_slot_drinks: "Đồ uống",
    faq_a_new_me_tracking: "Chạm vào nhiệm vụ tiếp theo ở phía trên New Me rồi chạm ✓ Đã ăn để đánh dấu bữa tiếp theo đã ăn – toàn bộ thực đơn với ✓ cho từng bữa có trong Cả ngày, ở bên cạnh, và các bữa hôm nay cũng xuất hiện trong Ngày Của Tôi trên màn hình chính – chạm vào một bữa ở đó (hoặc rê chuột lên trên) sẽ hiện chính xác cần ăn gì, kèm ✓ và Đổi. Mọi thứ đồng bộ với Theo Dõi Bữa Ăn Hàng Ngày: các bữa theo kế hoạch, đồ uống và mọi thứ được thêm ở nơi khác (ví dụ một ly cà phê từ thêm nhanh) được tính chung trong New Me và trong Ngày Của Tôi – những gì đã nhập không bị ghi đè, và bỏ ✓ chỉ xóa phần của New Me. Khi tất cả các bữa hôm nay đã được đánh dấu sẽ có một màn ăn mừng nhỏ. Trong “Đồ uống”, ghi lại đồ uống trong ngày – tổng cộng tối đa ~150 kcal, tức khoảng 3 đồ uống, mỗi loại tối đa ~50 kcal. Chỉ cần gõ tên đồ uống, calo sẽ được AI tự điền. Hai dòng cà phê/trà còn có ô “Sữa? Bao nhiêu?” (ví dụ “một chút” hoặc “50 ml”), và phép tính được cập nhật; con số có thể thay đổi trước khi thêm và cả sau đó. Đồ uống có tên và calo được tự động lưu ngay khi chuyển sang việc khác – chạm Thêm là không bắt buộc. Chạm ☆ cạnh một đồ uống để lưu nó thành đồ uống quen thuộc – đồ uống quen thuộc hiện thành nút ở đầu thẻ Đồ uống, và một lần chạm sẽ thêm vào ngày. ⭐ lưu một bữa thành bữa đã lưu. “Bảng hằng ngày” cho thấy những gì đã ăn kèm calo và protein. Một 💎 nhỏ cạnh chế độ tập trung ở đầu màn hình chính mở thẳng New Me. Giá trị calo và protein là ước tính của AI và có thể có sai sót. Không ăn hết? Dưới một bữa đã đánh dấu, “Không ăn hết?” sẽ trừ một phần tư, một nửa hoặc ba phần tư khẩu phần – hoặc phần bạn ghi, được tính toán – và calo trong ngày được cập nhật.",
    faq_q_new_me_tracking: "Dấu ✓, đổi món và calo hoạt động thế nào trong New Me?",
    faq_a_new_me_what: "New Me là chương trình thực đơn hằng ngày riêng biệt với hai kế hoạch soạn sẵn – 1.300 hoặc 1.500 calo – gồm 2 bữa chính và 2 bữa phụ, mỗi bữa có 3 lựa chọn. Chương trình bao gồm toàn bộ Premium. Giá: $11.99 mỗi tháng (hủy bất cứ lúc nào) hoặc $99.99 một lần, trọn đời. Mở từ 💎 New Me trong menu. Trước khi bắt đầu có một bảng câu hỏi ngắn mở đầu bằng tuyên bố miễn trừ y tế cần chấp nhận. Chương trình chỉ là thông tin chung và không thay thế bác sĩ hay chuyên gia dinh dưỡng lâm sàng.",
    faq_q_new_me_what: "New Me là gì và làm sao để có?",
