    faq_q_calorie_monthly_view: "Làm sao để xem lịch sử calo của cả một tháng?", faq_a_calorie_monthly_view: "Chỉ Số Calo và Cân Nặng có thẻ 'Xem Theo Tháng' với lịch - mỗi ngày bạn ghi lại món ăn sẽ có một chấm, và mức trung bình hàng ngày của tháng đó được hiển thị phía trên lưới. Chạm vào bất kỳ ngày nào để xem chính xác bạn đã ăn gì và tổng số. Cùng một bảng chi tiết đó cũng được đưa vào khi bạn tải Báo Cáo Cá Nhân (PDF) từ Cài Đặt, nếu mục Chỉ Số Calo và Cân Nặng được chọn.",
    faq_q_calorie_stats_total_vs_average: "Con số Hàng Tuần/Hàng Tháng trong Chỉ Số Calo và Cân Nặng là tổng hay trung bình?", faq_a_calorie_stats_total_vs_average: "Cả hai - con số lớn là tổng (sum) của mọi thứ được ghi trong tuần/tháng lịch hiện tại, còn dòng nhỏ bên dưới là mức trung bình hàng ngày. Mức trung bình chỉ được chia cho số ngày bạn thực sự có ghi chép, không phải chia cho 7 hay cả tháng - một ngày không có ghi chép nào sẽ đơn giản là được bỏ qua, không tính là 0 và không kéo mức trung bình xuống.",
    faq_q_weight_note: "Tôi có thể thêm ghi chú vào một mục cân nặng không?", faq_a_weight_note: "Có - có một trường ghi chú tùy chọn bên cạnh các ô cân nặng/ngày trong Theo Dõi Cân Nặng Định Kỳ (nằm ở cuối Dinh Dưỡng & Chỉ Số > Chỉ Số Calo và Cân Nặng, trong mục ⚖️). Bạn có thể dùng nó để ghi thêm ngữ cảnh như \"sau khi tập luyện\" hoặc \"cân buổi sáng\" - ghi chú sẽ hiện bên cạnh mục đó trong danh sách lịch sử.",
