    faq_q_daily_focus_prompt: "Lời nhắc nhỏ hỏi điều quan trọng nhất tôi cần làm hôm nay là gì?", faq_a_daily_focus_prompt: "Đây là lời nhắc hằng ngày của Premium: mỗi ngày một lần, một huy hiệu nhỏ “1” xuất hiện trên biểu tượng trợ lý AI. Chạm vào huy hiệu để mở một bong bóng hỏi điều gì quan trọng nhất với bạn hôm nay, với 5 gợi ý có sẵn hiện ngay trong đó (thay đổi mỗi ngày, luân phiên qua các chủ đề khác nhau suốt cả năm để luôn mới mẻ) cùng với 'Khác' để tự viết - bạn có thể chọn nhiều hơn một. Chạm Thêm, và các lựa chọn của bạn sẽ hiện thành các nhãn nhắc nhở nhỏ ở đầu 'Ngày Của Tôi' (đây không phải việc cần đánh dấu). Nếu bạn đóng bằng ✕ hoặc chạm ra ngoài, huy hiệu chỉ mờ đi trong phần còn lại của ngày thay vì biến mất. Tính năng này bật theo mặc định, nhưng bạn có thể tắt trong Cài đặt > Cá Nhân Hóa & Lịch. Hôm nay không tiện? Nhấn '🌙 Hôm nay thôi' – huy hiệu sẽ ẩn đến mai, rồi câu hỏi quay lại như thường lệ. Một trong các gợi ý đến từ chính cuộc sống của bạn – bước tiếp theo của mục tiêu tháng hoặc việc đọc hôm nay. Mỗi ngày là một khởi đầu mới.",
    food_input_placeholder: "Bạn đã ăn gì?", calories_input_placeholder: "Calo", snack_input_placeholder: "Đồ ăn vặt...",
    nutrition_multi_food_tip: "💡 Đang ghi vài món ăn trong cùng một dòng? Hãy tách chúng bằng dấu phẩy hoặc \"+\" để ước tính calo chính xác hơn.",
