    habits_title: "Thói quen", habits_empty_hint: "Chưa có thói quen nào - thêm một cái để bắt đầu theo dõi chuỗi ngày của bạn.", habits_add_modal_title: "Thói quen mới", habits_name_placeholder: "vd. Uống nước, Đọc sách, Thiền...", habits_missing_name: "Vui lòng đặt tên cho thói quen", habits_delete_title: "Xóa thói quen này?", habits_delete_confirm: "Thao tác này cũng sẽ xóa vĩnh viễn toàn bộ lịch sử và chuỗi ngày của nó.", habits_link_sport_label: "Cũng ghi lại đây như một buổi thể thao khi hoàn thành", habits_sport_duration_placeholder: "Thời lượng (phút)", habits_missing_sport_duration: "Nhập thời lượng bằng phút", habit_auto_logged_sport_badge: "Từ một thói quen", habits_overview_btn_title: "Tổng quan hàng tháng", habits_overview_title: "Thói quen - Tổng quan hàng tháng", routine_goals_section_title: "🎯 Mục Tiêu & Thói Quen", routine_goals_empty_hint: "Tab này chưa có gì - hãy thêm mục vào thói quen của bạn để theo dõi tại đây.", routine_goals_toggle_label: "Hiển thị theo dõi mục tiêu & thói quen",
