    schedule_move_slot_title: "Chuyển sang ngày khác", schedule_move_slot_confirm_btn: "Chuyển", schedule_move_slot_empty: "Thêm tiêu đề cho công việc này trước khi chuyển nó", schedule_move_slot_success: "Đã chuyển công việc ✅",
